export type AiEventType = "$ai_generation" | "$ai_embedding" | "$ai_span" | "$ai_trace" | "$ai_metric" | "$ai_feedback" | "$ai_evaluation" | "$ai_tag" | "$ai_trace_summary" | "$ai_generation_summary" | "$ai_trace_clusters" | "$ai_generation_clusters";

export type AiPromptConfig = {
  /** Analysis window for the report. Omitted = 'since_last_sent' (everything since the previous scheduled delivery). */
  window?: AiWindowConfig;
};

export type AiReportQueryDiagnostic = {
  /** What this query step was meant to compute. */
  description: string;
  /** The HogQL the assistant generated for this step. */
  hogql: string;
  /** Whether the query ran successfully. */
  ok: boolean;
  /** Exception class name when the query failed; null on success. */
  error_type: string | null;
  /** Human-readable failure reason, present only for query errors safe to surface to the subscription owner (e.g. an unresolved field name); null on success and for internal errors, which expose error_type only. */
  human_readable_error?: string | null;
};

export type AiWindowConfig = {
  /** What the report analyzes each run: * `since_last_sent` (default) — everything since the previous successful scheduled delivery (gap-free; test/manual sends don't move the anchor) * `last_n_days` — a fixed trailing window of start_days_ago days * `days_ago_range` — the explicit range from start_days_ago to end_days_ago days ago  * `since_last_sent` - Since last report * `last_n_days` - Last N days * `days_ago_range` - Between X and Y days ago */
  mode?: AiWindowConfigModeEnum;
  /** Lower bound of the analysis window, in days before the run. Required for 'last_n_days' (the N) and 'days_ago_range'; ignored for 'since_last_sent'. 1-365. */
  start_days_ago?: number | null;
  /** Upper bound of the analysis window, in days before the run (0 = now). Required for 'days_ago_range' and must be less than start_days_ago; ignored for other modes. 0-365. */
  end_days_ago?: number | null;
};

/** * `since_last_sent` - Since last report * `last_n_days` - Last N days * `days_ago_range` - Between X and Y days ago */
export type AiWindowConfigModeEnum = "since_last_sent" | "last_n_days" | "days_ago_range";

export type AccessControlFilterWarning = {
  /** Human-readable warning shown to the user */
  message: string;
  /** Resource types the user has access restrictions on, referenced by the query, e.g. ["insight", "dashboard"] */
  resources: (string)[];
  /** Tells warning kinds apart in the shared `warnings` list */
  type?: string;
};

export type AccessControlLevel = "none" | "member" | "admin" | "viewer" | "editor" | "manager";

/** * `read_write` - read_write * `read` - read * `none` - none */
export type AccessLevelEnum = "read_write" | "read" | "none";

/** * `warehouse` - warehouse * `direct` - direct */
export type AccessMethodEnum = "warehouse" | "direct";

/** A Customer Analytics account — a logical grouping used to assign customer-success ownership. */
export type Account = {
  id: string;
  /** Human-readable name of the account. */
  name: string;
  /** Identifier linking this account to its source customer — the analytics group key (the customer's organization id), used to match billing and external records. Optional. */
  external_id?: string | null;
  /** Typed account properties: assignment fields (csm, account_executive, account_owner) and external system identifiers (stripe_customer_id, hubspot_deal_id, billing_id, sfdc_id, zendesk_id, slack_channel_id, usage_dashboard_link). Defaults to an empty object. Unknown keys are rejected. */
  properties?: { [key: string]: unknown } | null;
  /** Tag names attached to the account. Pass a list to replace existing tags. */
  tags?: (string)[];
  /** Short IDs of the internal notebooks linked to this account, used to persist investigations, call notes, and other free-form context. Empty list if no notebooks have been created for the account. */
  notebooks: (string)[];
  created_at: string;
  created_by: number | null;
  updated_at: string | null;
};

/** A user assigned to an account relationship (read shape). */
export type AccountAssignment = {
  /** PostHog user id of the assignee. */
  id: number;
  /** Email of the assignee. */
  email: string;
};

/** A team-wide account note — an internal notebook linked to a Customer analytics account. */
export type AccountNote = {
  /** URL-safe short ID of the notebook. */
  short_id: string;
  /** Title of the note. */
  title: string | null;
  /** When the note was created. */
  created_at: string;
  /** When the note was last modified. */
  last_modified_at: string;
  /** UUID of the account this note is linked to. */
  account_id: string;
  /** Name of the account this note is linked to. */
  account_name: string;
  /** User who created the note, if known. */
  created_by: UserBasic | null;
};

export type AccountNotebook = {
  id: string;
  short_id: string;
  /** Human-readable title of the account notebook. */
  title?: string | null;
  /** Notebook content as a ProseMirror JSON document structure. */
  content?: unknown;
  /** Plain text representation of the notebook content for search. */
  text_content?: string | null;
  created_at: string;
  created_by: UserBasic;
  last_modified_at: string;
  last_modified_by: UserBasic;
};

/** One assignment of a user to an account relationship, with its effective range. */
export type AccountRelationship = {
  /** Unique id of this assignment row. */
  id: string;
  /** The relationship type this assignment belongs to. */
  definition: AccountRelationshipDefinition;
  /** The assigned user; null when their account was deleted. */
  user: AccountAssignment | null;
  /** When this assignment became effective. */
  started_at: string;
  /** When this assignment ended; null while it is active. */
  ended_at: string | null;
};

/** A team-defined account relationship type (CSM, Onboarding manager, ...). */
export type AccountRelationshipDefinition = {
  /** Relationship definition UUID. */
  id: string;
  /** Human-readable name of the relationship. Unique within the team. */
  name: string;
  /** What this relationship means, e.g. 'The customer success manager responsible for this account'. */
  description?: string | null;
  /** Whether only one user can hold this relationship per account at a time, e.g. a single CSM per account. */
  is_single_holder?: boolean;
};

/** Input for assigning a user to an account relationship. */
export type AccountRelationshipWrite = {
  /** Id of the relationship definition to assign. */
  definition: string;
  /** PostHog user id of the assignee. Must be a member of the account's organization. */
  user: number;
};

export type AccountsQuery = {
  /** Match accounts with no active relationship of any definition. */
  allRolesUnassigned?: boolean | null;
  /** Match accounts where any of these user ids actively holds any relationship (CSM, Account executive, or a custom definition). Drives the "My accounts" shortcut (the current user's id) and the shareable "Assigned to" filter — the ids are explicit so a shared URL resolves identically for every viewer. */
  assignedToUserIds?: (number)[] | null;
  /** Optional HogQL boolean expression AND-ed into the WHERE clause. Used by the overview tile click-to-filter affordance. */
  filterExpression?: string | null;
  kind?: string;
  limit?: number | null;
  /** Aggregation expressions evaluated against the filtered account set; one value per metric is returned in `metricsResults`. When `metrics` is set without a `select`, the runner skips the regular row fetch and returns only the aggregated values. */
  metrics?: (string)[] | null;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  offset?: number | null;
  orderBy?: (string)[] | null;
  response?: AccountsQueryResponse | null;
  search?: string | null;
  select?: (string)[] | null;
  tagNames?: (string)[] | null;
  tags?: QueryLogTags | null;
  /** version of the node, used for schema migrations */
  version?: number | null;
};

export type AccountsQueryResponse = {
  columns: (unknown)[];
  /** Query error. Returned only if 'explain' or `modifiers.debug` is true. Throws an error otherwise. */
  error?: string | null;
  hasMore?: boolean | null;
  /** Generated HogQL query. */
  hogql: string;
  kind?: string;
  limit: number;
  /** When `metrics` is set on the query, the aggregated values in the same order. */
  metricsResults?: (number | null)[] | null;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  offset: number;
  /** Query status indicates whether next to the provided data, a query is still running. */
  query_status?: QueryStatus | null;
  /** The resolved previous/comparison period date range, when comparing against another period */
  resolved_compare_date_range?: ResolvedDateRangeResponse | null;
  /** The date range used for the query */
  resolved_date_range?: ResolvedDateRangeResponse | null;
  results: ((unknown)[])[];
  /** Measured timings for different parts of the query generation process */
  timings?: (QueryTiming)[] | null;
  types: (string)[];
  /** Warnings about data warehouse sources referenced by the query whose latest sync failed, is paused, hit a billing limit, or is otherwise stale. Results may not reflect current source data. Accumulated across every HogQL execution that contributes to this response — so insights backed by warehouse tables (Trends, Funnels, etc.) receive the same warnings as raw HogQL queries. Also carries access control warnings when a system-table query filters out objects the user can't access. */
  warnings?: (DataWarehouseSyncWarning | AccessControlFilterWarning)[] | null;
};

export type AchievementDefinition = {
  /** Stable track identifier, e.g. 'streak'. */
  key: string;
  /** Human-readable track name. */
  display_name: string;
  /** One-line description of what the track rewards. */
  description: string;
  /** Whether the track is tracked per user or per team.  * `user` - user * `team` - team */
  scope: AchievementDefinitionScopeEnum;
  /** True for the streak track, whose thresholds vary by the streak-cadence experiment arm. */
  is_experiment_track: boolean;
  /** The five stages of this track, in ascending threshold order. */
  stages: (AchievementStage)[];
};

/** * `user` - user * `team` - team */
export type AchievementDefinitionScopeEnum = "user" | "team";

export type AchievementProgress = {
  /** Track this progress row belongs to. */
  track_key: string;
  /** Highest stage unlocked so far, 0-5. */
  current_stage: number;
  /** Most recently computed progress value for the track. */
  progress_value: number;
  /** When the track was last recomputed, or null if it never has been. */
  last_computed_at: string | null;
  /** Map of unlocked stage number (as a string, '1'-'5') to the ISO timestamp it was unlocked. */
  unlocked_at: { [key: string]: string | undefined };
};

export type AchievementStage = {
  /** Stage number within the track, 1-5. */
  stage: number;
  /** Stage name within the track, e.g. 'On a roll'. */
  name: string;
  /** Progress value needed to unlock this stage, resolved for the user's streak arm. */
  threshold: number;
};

export type AchievementsListResponse = {
  /** All Wave-1 track definitions, thresholds resolved for the user's streak arm. */
  definitions: (AchievementDefinition)[];
  /** The requesting user's progress on per-user tracks. */
  user_progress: (AchievementProgress)[];
  /** The team's progress on per-team tracks. */
  team_progress: (AchievementProgress)[];
  /** Newly unlocked stages awaiting an in-session celebration; acknowledge each to clear it. */
  pending_celebrations: (PendingCelebration)[];
};

export type AcknowledgeCelebrationRequest = {
  /** Track of the celebration being acknowledged. */
  track_key: string;
  /** Stage number being acknowledged, 1-5. */
  stage: number;
};

export type AcknowledgeCelebrationResponse = {
  /** True if a matching pending celebration was cleared (idempotent). */
  acknowledged: boolean;
};

/** Serializer mixin that handles tags for objects. */
export type Action = {
  id: number;
  /** Name of the action (must be unique within the project). */
  name?: string | null;
  /** Human-readable description of what this action represents. */
  description?: string;
  tags?: (unknown)[];
  /** Whether to post a notification to Slack when this action is triggered. */
  post_to_slack?: boolean;
  /** Custom Slack message format. Supports templates with event properties. */
  slack_message_format?: string;
  /** Action steps defining trigger conditions. Each step matches events by name, properties, URL, or element attributes. Multiple steps are OR-ed together. */
  steps?: (ActionStepJson)[];
  created_at: string;
  created_by: UserBasic;
  deleted?: boolean;
  is_calculating: boolean;
  last_calculated_at?: string;
  team_id: number;
  is_action: boolean;
  bytecode_error: string | null;
  /** ISO 8601 timestamp when the action was pinned, or null if not pinned. Set any value to pin, null to unpin. */
  pinned_at?: string | null;
  creation_context: string | null;
  _create_in_folder?: string;
  /** The effective access level the user has for this object */
  user_access_level: string | null;
};

export type ActionConversionGoal = {
  actionId: number;
};

export type ActionReference = {
  /** Resource type: insight, experiment, cohort, or hog_function */
  type: string;
  /** Resource ID (integer or UUID depending on type) */
  id: string;
  /** Resource name */
  name: string;
  /** Relative URL to the resource */
  url: string;
  /** When the resource was created */
  created_at: string | null;
  /** User who created the resource */
  created_by: UserBasic | null;
};

export type ActionStepJson = {
  /** Event name to match (e.g. '$pageview', '$autocapture', or a custom event name). */
  event?: string | null;
  /** Event or person property filters. Each item should have 'key' (string), 'value' (string, number, boolean, or array), optional 'operator' (exact, is_not, is_set, is_not_set, icontains, not_icontains, regex, not_regex, gt, gte, lt, lte), and optional 'type' (event, person). */
  properties?: unknown[] | null;
  /** CSS selector to match the target element (e.g. 'div > button.cta'). */
  selector?: string | null;
  selector_regex: string | null;
  /** HTML tag name to match (e.g. "button", "a", "input"). */
  tag_name?: string | null;
  /** Element text content to match. */
  text?: string | null;
  /** How to match the text value. Defaults to exact.  * `contains` - contains * `regex` - regex * `exact` - exact */
  text_matching?: ActionStepMatchingEnum | NullEnum;
  /** Link href attribute to match. */
  href?: string | null;
  /** How to match the href value. Defaults to exact.  * `contains` - contains * `regex` - regex * `exact` - exact */
  href_matching?: ActionStepMatchingEnum | NullEnum;
  /** Page URL to match. */
  url?: string | null;
  /** How to match the URL value. Defaults to contains.  * `contains` - contains * `regex` - regex * `exact` - exact */
  url_matching?: ActionStepMatchingEnum | NullEnum;
};

/** * `contains` - contains * `regex` - regex * `exact` - exact */
export type ActionStepMatchingEnum = "contains" | "regex" | "exact";

export type ActionStepPropertyFilter = StringPropertyFilter | NumericPropertyFilter | ArrayPropertyFilter | DatePropertyFilter | ExistencePropertyFilter;

/** * `immediately_actionable` - immediately_actionable * `requires_human_input` - requires_human_input * `not_actionable` - not_actionable */
export type ActionabilityEnum = "immediately_actionable" | "requires_human_input" | "not_actionable";

