/** Matches against a list of values (OR semantics for exact/is_not, set membership for in/not_in). */
export type ArrayPropertyFilter = {
  /** Key of the property you're filtering on. For example `email` or `$current_url`. */
  key: string;
  /** Property type (event, person, session, etc.).  * `event` - event * `event_metadata` - event_metadata * `feature` - feature * `person` - person * `person_metadata` - person_metadata * `cohort` - cohort * `element` - element * `static-cohort` - static-cohort * `dynamic-cohort` - dynamic-cohort * `precalculated-cohort` - precalculated-cohort * `group` - group * `recording` - recording * `log_entry` - log_entry * `behavioral` - behavioral * `session` - session * `hogql` - hogql * `data_warehouse` - data_warehouse * `data_warehouse_person_property` - data_warehouse_person_property * `error_tracking_issue` - error_tracking_issue * `log` - log * `log_attribute` - log_attribute * `log_resource_attribute` - log_resource_attribute * `metric_attribute` - metric_attribute * `span` - span * `span_attribute` - span_attribute * `span_resource_attribute` - span_resource_attribute * `revenue_analytics` - revenue_analytics * `flag` - flag * `workflow_variable` - workflow_variable */
  type?: PropertyFilterTypeEnum;
  /** List of values to match. For example `["test@example.com", "ok@example.com"]`. */
  value: (string)[];
  /** Array comparison operator.  * `exact` - exact * `is_not` - is_not * `in` - in * `not_in` - not_in */
  operator?: ArrayPropertyFilterOperatorEnum;
};

/** * `exact` - exact * `is_not` - is_not * `in` - in * `not_in` - not_in */
export type ArrayPropertyFilterOperatorEnum = "exact" | "is_not" | "in" | "not_in";

