/** Typed configuration for an AWS S3 batch-export destination.  AWS credentials live in the linked aws-s3 Integration. Mirrors the non-credential fields of `AwsS3BatchExportInputs` in `products/batch_exports/backend/service.py`. */
export type AwsS3DestinationConfig = {
  /** Name of the destination bucket. */
  bucket_name: string;
  /** Region the bucket is in (e.g. 'us-east-1'). */
  region: string;
  /** Object key prefix applied to every exported file. */
  prefix: string;
  /** Optional compression codec applied to exported files. Valid codecs depend on file_format.  * `brotli` - brotli * `gzip` - gzip * `lz4` - lz4 * `snappy` - snappy * `zstd` - zstd */
  compression?: CompressionEnum | NullEnum;
  /** File format used for exported objects.  * `Parquet` - Parquet * `JSONLines` - JSONLines */
  file_format?: FileFormatEnum;
  /** If set, rolls to a new file once the current file exceeds this size in MB. */
  max_file_size_mb?: number | null;
  /** Optional S3 server-side encryption algorithm (e.g. 'AES256' or 'aws:kms'). */
  encryption?: string | null;
  /** KMS key ID to use when encryption is 'aws:kms'. */
  kms_key_id?: string | null;
};

/** Request shape for creating or updating an AWS S3 batch-export destination. */
export type AwsS3DestinationRequest = {
  type: AwsS3DestinationRequestTypeEnum;
  /** ID of an aws-s3-kind Integration providing AWS credentials. Preferred over inline credentials. Use the integrations-list MCP tool to find one. */
  integration_id?: number;
  config: AwsS3DestinationConfig;
};

/** * `AwsS3` - AwsS3 */
export type AwsS3DestinationRequestTypeEnum = "AwsS3";

