/** One row in `inventory.external_data_sources`. */
export type ExternalDataSourceEntry = {
  /** Warehouse source type (e.g. `Stripe`, `Postgres`, `BigQuery`). */
  source_type: string;
  /** Current sync status (`Running`, `Failed`, `Paused`, etc.). */
  status: string;
  /** Schema prefix used by this source, if any. */
  prefix: string;
  /** ISO-8601 timestamp the source was connected. */
  created_at: string | null;
  /** ISO-8601 timestamp of the most recent completed sync job, or null if this source has never completed a sync. Use this to tell a healthy source apart from one stuck in `Running` that has imported zero rows — `status` alone conflates the two. */
  last_run_at: string | null;
  /** Newest schema-level sync error for this source, or null if no schema is erroring. */
  latest_error: string | null;
};

export type ExternalDataSourceRevenueAnalyticsConfig = {
  enabled?: boolean;
  include_invoiceless_charges?: boolean;
};

/** Mixin for serializers to add user access control fields */
export type ExternalDataSourceSerializers = {
  id: string;
  created_at: string;
  created_by: string | null;
  /** How this source was created. Defaults to `api` on create when omitted. `web` for the in-app UI, `api` for direct API callers, `mcp` for agent/MCP tool calls. Ignored on update.  * `web` - web * `api` - api * `mcp` - mcp */
  created_via?: CreatedViaEnum | NullEnum;
  status: string;
  client_secret: string;
  account_id: string;
  source_type: ExternalDataSourceTypeEnum;
  latest_error: string | null;
  prefix?: string | null;
  description?: string | null;
  access_method: AccessMethodEnum;
  /** Whether this synced source is also live-queryable via direct connection. Defaults to true for new sources; ignored for pure direct-query sources. */
  direct_query_enabled?: boolean;
  /** Backend engine detected for the direct connection.  * `duckdb` - duckdb * `postgres` - postgres * `mysql` - mysql * `snowflake` - snowflake */
  engine: EngineEnum | NullEnum;
  last_run_at: string | null;
  schemas: ({ [key: string]: unknown })[];
  job_inputs?: unknown;
  revenue_analytics_config: ExternalDataSourceRevenueAnalyticsConfig;
  /** The effective access level the user has for this object */
  user_access_level: string | null;
  supports_webhooks: boolean;
  /** Whether this source supports per-column sync selection via `enabled_columns`. */
  supports_column_selection: boolean;
};

