export type SessionsQuery = {
  /** Filter sessions by action - sessions that contain events matching this action */
  actionId?: number | null;
  /** Only fetch sessions that started after this timestamp */
  after?: string | null;
  /** Only fetch sessions that started before this timestamp */
  before?: string | null;
  /** Filter sessions by event name - sessions that contain this event */
  event?: string | null;
  /** Event property filters - filters sessions that contain events matching these properties */
  eventProperties?: (EventPropertyFilter | PersonPropertyFilter | PersonMetadataPropertyFilter | ElementPropertyFilter | EventMetadataPropertyFilter | SessionPropertyFilter | CohortPropertyFilter | RecordingPropertyFilter | LogEntryPropertyFilter | GroupPropertyFilter | FeaturePropertyFilter | FlagPropertyFilter | HogQlPropertyFilter | EmptyPropertyFilter | DataWarehousePropertyFilter | DataWarehousePersonPropertyFilter | ErrorTrackingIssueFilter | LogPropertyFilter | MetricPropertyFilter | SpanPropertyFilter | RevenueAnalyticsPropertyFilter | WorkflowVariablePropertyFilter)[] | null;
  /** Filter test accounts */
  filterTestAccounts?: boolean | null;
  /** Fixed properties in the query, can't be edited in the interface (e.g. scoping down by person) */
  fixedProperties?: (PropertyGroupFilter | PropertyGroupFilterValue | EventPropertyFilter | PersonPropertyFilter | PersonMetadataPropertyFilter | ElementPropertyFilter | EventMetadataPropertyFilter | SessionPropertyFilter | CohortPropertyFilter | RecordingPropertyFilter | LogEntryPropertyFilter | GroupPropertyFilter | FeaturePropertyFilter | FlagPropertyFilter | HogQlPropertyFilter | EmptyPropertyFilter | DataWarehousePropertyFilter | DataWarehousePersonPropertyFilter | ErrorTrackingIssueFilter | LogPropertyFilter | MetricPropertyFilter | SpanPropertyFilter | RevenueAnalyticsPropertyFilter | WorkflowVariablePropertyFilter)[] | null;
  kind?: string;
  /** Number of rows to return */
  limit?: number | null;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  /** Number of rows to skip before returning rows */
  offset?: number | null;
  /** Columns to order by */
  orderBy?: (string)[] | null;
  /** Show sessions for a given person */
  personId?: string | null;
  /** Properties configurable in the interface */
  properties?: (EventPropertyFilter | PersonPropertyFilter | PersonMetadataPropertyFilter | ElementPropertyFilter | EventMetadataPropertyFilter | SessionPropertyFilter | CohortPropertyFilter | RecordingPropertyFilter | LogEntryPropertyFilter | GroupPropertyFilter | FeaturePropertyFilter | FlagPropertyFilter | HogQlPropertyFilter | EmptyPropertyFilter | DataWarehousePropertyFilter | DataWarehousePersonPropertyFilter | ErrorTrackingIssueFilter | LogPropertyFilter | MetricPropertyFilter | SpanPropertyFilter | RevenueAnalyticsPropertyFilter | WorkflowVariablePropertyFilter)[] | null;
  response?: SessionsQueryResponse | null;
  /** Return a limited set of data. Required. */
  select: (string)[];
  tags?: QueryLogTags | null;
  /** version of the node, used for schema migrations */
  version?: number | null;
  /** HogQL filters to apply on returned data */
  where?: (string)[] | null;
};

export type SessionsQueryResponse = {
  columns: (unknown)[];
  /** Query error. Returned only if 'explain' or `modifiers.debug` is true. Throws an error otherwise. */
  error?: string | null;
  hasMore?: boolean | null;
  /** Generated HogQL query. */
  hogql: string;
  limit?: number | null;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  offset?: number | null;
  /** Query status indicates whether next to the provided data, a query is still running. */
  query_status?: QueryStatus | null;
  /** The resolved previous/comparison period date range, when comparing against another period */
  resolved_compare_date_range?: ResolvedDateRangeResponse | null;
  /** The date range used for the query */
  resolved_date_range?: ResolvedDateRangeResponse | null;
  results: ((unknown)[])[];
  /** Measured timings for different parts of the query generation process */
  timings?: (QueryTiming)[] | null;
  types: (string)[];
  /** Warnings about data warehouse sources referenced by the query whose latest sync failed, is paused, hit a billing limit, or is otherwise stale. Results may not reflect current source data. Accumulated across every HogQL execution that contributes to this response — so insights backed by warehouse tables (Trends, Funnels, etc.) receive the same warnings as raw HogQL queries. Also carries access control warnings when a system-table query filters out objects the user can't access. */
  warnings?: (DataWarehouseSyncWarning | AccessControlFilterWarning)[] | null;
};

export type SessionsTimelineQuery = {
  /** Only fetch sessions that started after this timestamp (default: '-24h') */
  after?: string | null;
  /** Only fetch sessions that started before this timestamp (default: '+5s') */
  before?: string | null;
  kind?: string;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  /** Fetch sessions only for a given person */
  personId?: string | null;
  response?: SessionsTimelineQueryResponse | null;
  tags?: QueryLogTags | null;
  /** version of the node, used for schema migrations */
  version?: number | null;
};

export type SessionsTimelineQueryResponse = {
  /** Query error. Returned only if 'explain' or `modifiers.debug` is true. Throws an error otherwise. */
  error?: string | null;
  hasMore?: boolean | null;
  /** Generated HogQL query. */
  hogql?: string | null;
  /** Modifiers used when performing the query */
  modifiers?: HogQlQueryModifiers | null;
  /** Query status indicates whether next to the provided data, a query is still running. */
  query_status?: QueryStatus | null;
  /** The resolved previous/comparison period date range, when comparing against another period */
  resolved_compare_date_range?: ResolvedDateRangeResponse | null;
  /** The date range used for the query */
  resolved_date_range?: ResolvedDateRangeResponse | null;
  results: (TimelineEntry)[];
  /** Measured timings for different parts of the query generation process */
  timings?: (QueryTiming)[] | null;
  /** Warnings about data warehouse sources referenced by the query whose latest sync failed, is paused, hit a billing limit, or is otherwise stale. Results may not reflect current source data. Accumulated across every HogQL execution that contributes to this response — so insights backed by warehouse tables (Trends, Funnels, etc.) receive the same warnings as raw HogQL queries. Also carries access control warnings when a system-table query filters out objects the user can't access. */
  warnings?: (DataWarehouseSyncWarning | AccessControlFilterWarning)[] | null;
};

export type SessionsV2JoinMode = "string" | "uuid";

/** Body shape for AgentApplicationViewSet.env_keys_set — single secret upsert.  The view merges `{KEY: value}` into the existing encrypted env block without touching other keys, so callers can set or rotate one secret without needing to read the whole block back. */
export type SetEnvKeyRequest = {
  value: string;
};

/** Body shape for AgentApplicationViewSet.set_env.  `env` is a JSON object of string→string. The view encrypts it via the same Fernet schedule the worker uses to decrypt. */
export type SetEnvRequest = {
  env: { [key: string]: string | undefined };
};

/** Body for PUT /revisions/<id>/skill_refs/ — full-replace the draft's references. */
export type SetSkillRefsRequest = {
  /** The complete set of store-skill references for this draft; replaces any existing references. */
  skill_refs: (SkillRef)[];
};

export type Settings = {
  display?: ChartSettingsDisplay | null;
  formatting?: ChartSettingsFormatting | null;
};

/** * `trace` - trace * `debug` - debug * `info` - info * `warn` - warn * `error` - error * `fatal` - fatal */
export type SeverityLevelsEnum = "trace" | "debug" | "info" | "warn" | "error" | "fatal";

export type SharePassword = {
  id: number;
  created_at: string;
  note?: string | null;
  created_by_email: string;
  is_active: boolean;
};

export type SharingConfiguration = {
  created_at: string;
  enabled?: boolean;
  access_token: string | null;
  settings?: unknown;
  password_required?: boolean;
  share_passwords: (SharePassword)[];
};

export type ShipVariant = {
  /** The conclusion of the experiment.  * `won` - won * `lost` - lost * `inconclusive` - inconclusive * `stopped_early` - stopped_early * `invalid` - invalid */
  conclusion?: ConclusionEnum | NullEnum;
  /** Optional comment about the experiment conclusion. */
  conclusion_comment?: string | null;
  /** When true, open a draft pull request that removes the experiment's feature-flag code from the linked repository. Requires the requesting user to have access to PostHog Code (403 otherwise). Only acts for allowlisted teams; ignored otherwise. */
  open_cleanup_pr?: boolean;
  /** The key of the variant to ship. */
  variant_key: string;
  /** If true, prepend a release condition to the feature flag that rolls the variant out to 100% of users, overriding any existing release conditions on the flag. If false (default), only update the variant distribution — existing release conditions are preserved and the variant is served only to users who already match them. */
  release_to_everyone?: boolean;
};

/** * `above` - Above * `below` - Below * `hidden` - Hidden */
export type ShortcutPositionEnum = "above" | "below" | "hidden";

export type SignalExtra = SessionProblemSignalExtra | LlmEvalSignalExtra | LlmEvalReportSignalExtra | ZendeskTicketSignalExtra | GithubIssueSignalExtra | LinearIssueSignalExtra | ConversationsTicketSignalExtra | ErrorTrackingSignalExtra | PgAnalyzeIssueSignalExtra | EndpointExecutionFailedSignalExtra | EndpointBreakdownLimitExceededSignalExtra | SignalsScoutSignalExtra | LogsAlertStateChangeSignalExtra | ReplayVisionScannerFindingSignalExtra | HealthCheckSignalExtra;

export type SignalMatchMetadata = MatchedMetadata | NoMatchMetadata;

export type SignalNode = {
  /** ClickHouse document id of the signal. */
  signal_id: string;
  /** The signal's human-readable description. */
  content: string;
  /** Product that emitted the signal.  * `session_replay` - session_replay * `llm_analytics` - llm_analytics * `github` - github * `linear` - linear * `zendesk` - zendesk * `conversations` - conversations * `error_tracking` - error_tracking * `endpoints` - endpoints * `pganalyze` - pganalyze * `signals_scout` - signals_scout * `logs` - logs * `health_checks` - health_checks * `replay_vision` - replay_vision */
  source_product: SignalSourceProduct;
  /** Signal type within the source product.  * `session_analysis_cluster` - session_analysis_cluster * `session_problem` - session_problem * `evaluation` - evaluation * `evaluation_report` - evaluation_report * `issue` - issue * `ticket` - ticket * `issue_created` - issue_created * `issue_reopened` - issue_reopened * `issue_spiking` - issue_spiking * `endpoint_execution_failed` - endpoint_execution_failed * `endpoint_breakdown_limit_exceeded` - endpoint_breakdown_limit_exceeded * `cross_source_issue` - cross_source_issue * `alert_state_change` - alert_state_change * `health_issue` - health_issue * `scanner_finding` - scanner_finding */
  source_type: SignalSourceType;
  /** Emitter-scoped id of the underlying object (issue, ticket, ...). */
  source_id: string;
  /** Signal weight in [0, 1]; drives report ranking. */
  weight: number;
  /** Emission timestamp. */
  timestamp: string;
  /** Product-specific payload; shape depends on (source_product, source_type). */
  extra: SignalExtra;
  /** Clustering match/no-match metadata, when present. */
  match_metadata?: SignalMatchMetadata | null;
};

export type SignalReport = {
  id: string;
  title: string | null;
  summary: string | null;
  status: SignalReportStatusEnum;
  total_weight: number;
  signal_count: number;
  signals_at_run: number;
  created_at: string;
  updated_at: string;
  artefact_count: number;
  /** P0–P4 from the latest priority judgment artefact (when present). */
  priority: string | null;
  /** Actionability choice from the latest actionability judgment artefact (when present). */
  actionability: string | null;
  /** Whether the issue appears already fixed, from the actionability judgment artefact. */
  already_addressed: boolean | null;
  /** Reason code from the latest dismissal artefact, set when the report was suppressed (when present). */
  dismissal_reason: string | null;
  /** Free-form note captured alongside the dismissal reason (when present). */
  dismissal_note: string | null;
  is_suggested_reviewer: boolean;
  /** Distinct source products contributing signals to this report (from ClickHouse). */
  source_products: (string)[];
  /** skill_name slug of the scout that authored this report, when scout-authored (from ClickHouse); null otherwise. */
  scout_name: string | null;
  /** PR URL from the latest implementation task run, if available. */
  implementation_pr_url: string | null;
};

export type SignalReportArtefact = {
  id: string;
  type: SignalReportArtefactTypeEnum;
  content: { [key: string]: unknown } | (unknown)[];
  created_at: string;
  updated_at: string | null;
  /** User the artefact is attributed to, when a user produced it. Null for task/system writes. */
  created_by: User2 | null;
  /** Task the artefact is attributed to, when an agent produced it. Null for user/system writes. */
  task_id: string | null;
};

/** Body for appending an artefact to a report.  Everything is append-only: log artefacts accumulate, status artefacts supersede the previous version (latest-wins). The `content` shape depends on `artefact_type` and is validated against the type's schema (see `products/signals/backend/artefact_schemas.py`). */
export type SignalReportArtefactLogCreate = {
  /** The artefact type. One of: actionability_judgment, code_reference, commit, dismissal, note, priority_judgment, repo_selection, safety_judgment, signal_finding, suggested_reviewers, task_run. Log types accumulate; status types (safety_judgment, actionability_judgment, priority_judgment, repo_selection, suggested_reviewers) are latest-wins — appending a new version supersedes the previous one as the report's canonical status. */
  artefact_type: string;
  /** The artefact payload as a JSON object or array; shape depends on artefact_type and is validated against its schema. */
  content: unknown;
};

/** * `video_segment` - Video Segment * `safety_judgment` - Safety Judgment * `actionability_judgment` - Actionability Judgment * `priority_judgment` - Priority Judgment * `signal_finding` - Signal Finding * `repo_selection` - Repo Selection * `suggested_reviewers` - Suggested Reviewers * `dismissal` - Dismissal * `code_reference` - Code Reference * `commit` - Commit * `task_run` - Task Run * `note` - Note * `title_change` - Title Change * `summary_change` - Summary Change */
export type SignalReportArtefactTypeEnum = "video_segment" | "safety_judgment" | "actionability_judgment" | "priority_judgment" | "signal_finding" | "repo_selection" | "suggested_reviewers" | "dismissal" | "code_reference" | "commit" | "task_run" | "note" | "title_change" | "summary_change";

/** Response shape for the log-artefact create/update endpoints — echoes the stored row. */
export type SignalReportArtefactWriteResponse = {
  /** The artefact's unique id. */
  id: string;
  /** The id of the report this artefact belongs to. */
  report_id: string;
  /** The artefact type. */
  type: string;
  /** The artefact payload, parsed from storage. */
  content: unknown;
  /** When the artefact was created. */
  created_at: string;
  /** When the artefact was last written — set on creation and refreshed on each edit. Null only for rows created before this field existed. */
  updated_at: string | null;
  /** Task the artefact is attributed to, when an agent produced it. Null for user writes. */
  task_id: string | null;
};

export type SignalReportBulkStateRequest = {
  /** Target state for the report. Use 'suppressed' to dismiss the report from the inbox, or 'potential' to snooze/reopen it for later review.  * `suppressed` - suppressed * `potential` - potential */
  state: SignalReportStateEnum;
  /** Optional canonical reason code for the dismissal. Must be one of: already_fixed, report_unclear, analysis_wrong, wontfix_intentional, wontfix_irrelevant, other — these match the inbox UI so the rationale renders as a labelled chip rather than a raw code. 'already_fixed' is a snooze, not a dismissal: pair it with state='potential' (restore) so the report reappears if the issue recurs. Use 'other' together with a dismissal_note for anything that doesn't fit a code.  * `already_fixed` - Already fixed * `report_unclear` - Report is unclear to me * `analysis_wrong` - Agent's analysis is wrong * `wontfix_intentional` - Won't fix - intentional behavior * `wontfix_irrelevant` - Won't fix - issue is real but insignificant * `other` - Something else… */
  dismissal_reason?: DismissalReasonEnum;
  /** Optional free-form note explaining the dismissal. Capped at 4000 characters. */
  dismissal_note?: string;
  /** Optional, only honored when state is 'potential'. Number of additional signals the report must accumulate before it is re-promoted into the pipeline — effectively snoozing it until then. Omit to let the report re-enter the pipeline on the next matching signal. */
  snooze_for?: number;
  /** Report ids to transition to `state` in one call (1–100). Duplicates are de-duplicated; each id is processed independently so one disallowed transition does not block the rest. `dismissal_reason`, `dismissal_note` and `snooze_for` apply to every id. */
  ids: (string)[];
};

export type SignalReportBulkStateResponse = {
  /** One result per requested id, in request order (after de-duplication). */
  results: (SignalReportBulkStateResult)[];
  /** Number of reports whose state was changed. */
  transitioned_count: number;
  /** Number of reports whose transition was not allowed. */
  skipped_count: number;
  /** Number of reports that failed on invalid request data. */
  failed_count: number;
  /** Number of requested ids not visible to the caller. */
  not_found_count: number;
};

export type SignalReportBulkStateResult = {
  /** The report id this result refers to. */
  id: string;
  /** One of: transitioned, skipped, failed, not_found. transitioned: the state change was applied. skipped: the transition was not allowed from the report's current status (a 409 on the single-report endpoint). failed: the request data was invalid for this report. not_found: no report with this id is visible to you. */
  outcome: string;
  /** The report's status after the transition. Present only when outcome is 'transitioned'. */
  status?: string | null;
  /** Human-readable explanation for non-transitioned outcomes (skipped / failed / not_found). */
  detail?: string | null;
};

/** * `suppressed` - suppressed * `potential` - potential */
export type SignalReportStateEnum = "suppressed" | "potential";

export type SignalReportStateRequest = {
  /** Target state for the report. Use 'suppressed' to dismiss the report from the inbox, or 'potential' to snooze/reopen it for later review.  * `suppressed` - suppressed * `potential` - potential */
  state: SignalReportStateEnum;
  /** Optional canonical reason code for the dismissal. Must be one of: already_fixed, report_unclear, analysis_wrong, wontfix_intentional, wontfix_irrelevant, other — these match the inbox UI so the rationale renders as a labelled chip rather than a raw code. 'already_fixed' is a snooze, not a dismissal: pair it with state='potential' (restore) so the report reappears if the issue recurs. Use 'other' together with a dismissal_note for anything that doesn't fit a code.  * `already_fixed` - Already fixed * `report_unclear` - Report is unclear to me * `analysis_wrong` - Agent's analysis is wrong * `wontfix_intentional` - Won't fix - intentional behavior * `wontfix_irrelevant` - Won't fix - issue is real but insignificant * `other` - Something else… */
  dismissal_reason?: DismissalReasonEnum;
  /** Optional free-form note explaining the dismissal. Capped at 4000 characters. */
  dismissal_note?: string;
  /** Optional, only honored when state is 'potential'. Number of additional signals the report must accumulate before it is re-promoted into the pipeline — effectively snoozing it until then. Omit to let the report re-enter the pipeline on the next matching signal. */
  snooze_for?: number;
};

/** * `potential` - Potential * `candidate` - Candidate * `in_progress` - In Progress * `pending_input` - Pending Input * `ready` - Ready * `resolved` - Resolved * `failed` - Failed * `deleted` - Deleted * `suppressed` - Suppressed */
export type SignalReportStatusEnum = "potential" | "candidate" | "in_progress" | "pending_input" | "ready" | "resolved" | "failed" | "deleted" | "suppressed";

/** * `implementation` - Implementation */
export type SignalReportTaskRelationshipEnum = "implementation";

/** Per-(team, skill) scout config: schedule, enablement, and emit posture.  One row per `signals-scout-*` skill on the team. The coordinator auto-creates a row when it discovers a scout skill; this serializer lets agents tune the row. */
export type SignalScoutConfig = {
  id: string;
  /** The `signals-scout-*` skill this config controls. Set at creation, not editable. */
  skill_name: string;
  /** Human-readable summary of what this scout investigates, sourced from the scout skill's `description` metadata. Use it for a quick steer on the scout's focus without loading the full skill body. Empty if the skill is not currently present on the team or carries no description. */
  description: string;
  /** Where this scout came from: `canonical` for a scout PostHog ships and maintains (seeded from `products/signals/skills/`), or `custom` for one a team hand-authored on this project. Use it to badge built-in vs custom scouts instead of a hardcoded name list. Defaults to `custom` if the skill is not currently present on the team. */
  scout_origin: ScoutOriginEnum;
  /** Whether this scout runs on its schedule. Disabled scouts are skipped by the coordinator. */
  enabled?: boolean;
  /** Whether the scout writes findings to the inbox. False = dry-run: it runs and logs but emits nothing. */
  emit?: boolean;
  /** Minutes between runs (30–43200). The scout runs once this interval has elapsed since its last run. */
  run_interval_minutes?: number;
  /** When the coordinator last dispatched this scout. Null if it has never run. */
  last_run_at: string | null;
  created_at: string;
};

/** Request body for registering a scout config without waiting for the coordinator tick.  Upsert keyed on `skill_name`: if the coordinator (or a concurrent caller) already registered the row, the provided tunables are applied to it instead. */
export type SignalScoutConfigCreate = {
  /** The `signals-scout-*` skill to register a config for. The skill must already exist on this project — author it via the skills store first. */
  skill_name: string;
  /** Whether this scout runs on its schedule. Defaults to true. */
  enabled?: boolean;
  /** Whether the scout writes findings to the inbox. False = dry-run: it runs and logs but emits nothing. Defaults to true. */
  emit?: boolean;
  /** Minutes between runs (30–43200). Defaults to 1440 (every 24 hours). */
  run_interval_minutes?: number;
};

/** One finding a scout run emitted to the inbox — the persisted, queryable record of *what* the run surfaced, returned by `signals-scout-runs-emissions-list`. The emitted text lives in `description`; `source_id` is the join key (`run:<run_id>:finding:<finding_id>`) back into the underlying signal store. */
export type SignalScoutEmission = {
  id: string;
  /** UUID of the `SignalScoutRun` that emitted this finding. */
  run_id: string;
  /** Stable id the finding was emitted under; matches an entry in the run's `emitted_finding_ids`. */
  finding_id: string;
  /** The emitted finding prose — the signal's `description` as surfaced to the inbox. */
  description: string;
  /** Agent's weight for the signal in [0, 1]. Drives ranking in the inbox. */
  weight: number;
  /** Agent's confidence the finding is real in [0, 1]. */
  confidence: number;
  /** Optional severity tag — one of P0, P1, P2, P3, P4 — or null if the run didn't set one.  * `P0` - P0 * `P1` - P1 * `P2` - P2 * `P3` - P3 * `P4` - P4 */
  severity: AutonomyPriorityEnum | NullEnum;
  /** Slug tags the scout attached to this finding (lowercase kebab-case, e.g. `cost-spike`). Empty list when the run set none. */
  tags: (string)[];
  /** Deterministic `run:<run_id>:finding:<finding_id>` — the join key into the underlying signal store. */
  source_id: string;
  /** ISO-8601 timestamp the finding was emitted. */
  emitted_at: string;
};

/** Response for an on-demand (`run now`) scout dispatch.  The run executes asynchronously on the Temporal worker, so there is no `SignalScoutRun` row yet at response time — the bridge row is created once the run's first turn starts. Poll the scout's runs (`signals-scout-runs-list`) to see the resulting run and its findings. */
export type SignalScoutManualRun = {
  /** The `signals-scout-*` skill that was dispatched. */
  skill_name: string;
  /** Temporal workflow id for the dispatched run. The run executes asynchronously; poll the scout's runs to see the resulting run row, its status, and any emitted findings. */
  workflow_id: string;
  /** True when a new run was dispatched. The endpoint returns 409 instead when a run for this scout is already in progress. */
  started: boolean;
};

/** Full `SignalScoutRun` projection used by `get-run`. Same shape as the summary today; kept distinct so future detail-only extensions (linked Signal rows, LLMA token-cost join) can land here without bloating the list response. */
export type SignalScoutRunDetail = {
  /** UUID of the bridge row. */
  run_id: string;
  /** Canonical skill name the run executed (e.g. `signals-scout-general`). */
  skill_name: string;
  /** Skill version snapshotted at run start. */
  skill_version: number;
  /** Status from the linked TaskRun: not_started | queued | in_progress | completed | failed | cancelled. */
  status: string;
  /** ISO-8601 timestamp the bridge row was created — the field `date_from` / `date_to` filter and order on. Use this (not `started_at`) as the `date_to` cursor when walking past the 100-row cap, so runs created in the gap between a boundary run's TaskRun and its bridge row aren't skipped. */
  created_at: string;
  /** ISO-8601 timestamp the TaskRun was created. */
  started_at: string;
  /** ISO-8601 timestamp the TaskRun completed; null while still running. */
  completed_at: string | null;
  /** UUID of the Tasks `Task` the scout span ran inside. */
  task_id?: string | null;
  /** UUID of the Tasks `TaskRun`. Pairs with `task_id` to deep-link. */
  task_run_id?: string | null;
  /** Relative deep-link to the Tasks UI for this run, e.g. `/project/{team_id}/tasks/{task_id}?runId={task_run_id}`. */
  task_url?: string | null;
  /** One-paragraph close-out the scout wrote at end-of-run. Empty string for runs that errored before close-out. The dedupe key for non-emitting runs. */
  summary: string;
  /** Full `error_message` from the linked TaskRun, surfaced only for failed/cancelled runs (null otherwise, including on success). Use `failure_reason` for a concise scan-friendly summary. */
  error?: string | null;
  /** Concise derived reason the run didn't complete cleanly — the first line of `error` (bounded), or a status-derived fallback. Null unless the run terminated failed/cancelled. Read this to see at a glance *why* a run emitted nothing without pulling full stack traces. */
  failure_reason?: string | null;
  /** Number of findings this run actually emitted to the inbox. 0 for runs that investigated but surfaced nothing, or ran dry-run / before AI approval. `> 0` means the run produced at least one `Signal`. */
  emitted_count: number;
  /** The `finding_id`s behind `emitted_count`, in emit order. Each maps to a `Signal` with `source_id = run:<run_id>:finding:<finding_id>`. Empty for non-emitting runs. */
  emitted_finding_ids: (string)[];
  /** The `SignalReport` ids this run authored directly via the `emit_report` channel, in emit order. Separate from `emitted_finding_ids` (weak `emit_signal` findings) — a report-authoring scout writes a full report here instead. Empty for runs that authored no report. */
  emitted_report_ids: (string)[];
  /** The `SignalReport` ids this run mutated via the `edit_report` channel (rewrote title/summary and/or appended a note), deduped. Distinct from `emitted_report_ids`: edit can target any inbox report, so these are generally not reports the run authored. Empty for runs that edited no report. */
  edited_report_ids: (string)[];
};

/** Lightweight projection of a `SignalScoutRun` row used by `search-recent-runs`.  Status and timestamps flow from the linked `tasks.TaskRun`. */
export type SignalScoutRunSummary = {
  /** UUID of the bridge row. */
  run_id: string;
  /** Canonical skill name the run executed (e.g. `signals-scout-general`). */
  skill_name: string;
  /** Skill version snapshotted at run start. */
  skill_version: number;
  /** Status from the linked TaskRun: not_started | queued | in_progress | completed | failed | cancelled. */
  status: string;
  /** ISO-8601 timestamp the bridge row was created — the field `date_from` / `date_to` filter and order on. Use this (not `started_at`) as the `date_to` cursor when walking past the 100-row cap, so runs created in the gap between a boundary run's TaskRun and its bridge row aren't skipped. */
  created_at: string;
  /** ISO-8601 timestamp the TaskRun was created. */
  started_at: string;
  /** ISO-8601 timestamp the TaskRun completed; null while still running. */
  completed_at: string | null;
  /** UUID of the Tasks `Task` the scout span ran inside. */
  task_id?: string | null;
  /** UUID of the Tasks `TaskRun`. Pairs with `task_id` to deep-link. */
  task_run_id?: string | null;
  /** Relative deep-link to the Tasks UI for this run, e.g. `/project/{team_id}/tasks/{task_id}?runId={task_run_id}`. */
  task_url?: string | null;
  /** One-paragraph close-out the scout wrote at end-of-run. Empty string for runs that errored before close-out. The dedupe key for non-emitting runs. */
  summary: string;
  /** Full `error_message` from the linked TaskRun, surfaced only for failed/cancelled runs (null otherwise, including on success). Use `failure_reason` for a concise scan-friendly summary. */
  error?: string | null;
  /** Concise derived reason the run didn't complete cleanly — the first line of `error` (bounded), or a status-derived fallback. Null unless the run terminated failed/cancelled. Read this to see at a glance *why* a run emitted nothing without pulling full stack traces. */
  failure_reason?: string | null;
  /** Number of findings this run actually emitted to the inbox. 0 for runs that investigated but surfaced nothing, or ran dry-run / before AI approval. `> 0` means the run produced at least one `Signal`. */
  emitted_count: number;
  /** The `finding_id`s behind `emitted_count`, in emit order. Each maps to a `Signal` with `source_id = run:<run_id>:finding:<finding_id>`. Empty for non-emitting runs. */
  emitted_finding_ids: (string)[];
  /** The `SignalReport` ids this run authored directly via the `emit_report` channel, in emit order. Separate from `emitted_finding_ids` (weak `emit_signal` findings) — a report-authoring scout writes a full report here instead. Empty for runs that authored no report. */
  emitted_report_ids: (string)[];
  /** The `SignalReport` ids this run mutated via the `edit_report` channel (rewrote title/summary and/or appended a note), deduped. Distinct from `emitted_report_ids`: edit can target any inbox report, so these are generally not reports the run authored. Empty for runs that edited no report. */
  edited_report_ids: (string)[];
};

